import type { HubCard, HubTone } from '../types'
import { words } from './words'

// The MODZ main panel's side of this mod (DESIGN.md §9): a one-line summary card it collects,
// and its "open" requests, which name a pane by key. Pure: register.tsx does the writing.

export const HUB_PANE = 'files'

export type HubShown = { detail: string; tone: HubTone }
// `edited` counts the files Claude wrote or committed in the latest turn; `sha` is that turn's commit.
export type HubInput = { isRunning: boolean; touched: number; hasRepo: boolean; changed: number; edited?: number; sha?: string }

const SHA_SHOWN = 7

// Live work first, then what git says is left to commit, then what the last turn did.
export function hubOf(s: HubInput): HubShown {
  const edited = s.edited ?? 0
  const w = words()
  if (s.isRunning && s.touched > 0) return { detail: w.hubLive(s.touched, edited), tone: 'live' }
  if (!s.hasRepo) return edited > 0 ? { detail: w.hubEditedLast(edited), tone: 'idle' } : { detail: w.hubNoRepo, tone: 'idle' }
  if (s.changed > 0) return { detail: w.hubUncommitted(s.changed), tone: 'warn' }
  if (s.sha) return { detail: w.hubCommit(s.sha.slice(0, SHA_SHOWN)), tone: 'ok' }

  return { detail: w.hubClean, tone: 'ok' }
}

// Written only when what the card shows changes, so the main panel does not redraw for nothing.
export function isSameCard(card: HubCard | undefined, shown: HubShown): boolean {
  return card !== undefined && card.detail === shown.detail && card.tone === shown.tone
}

export function isOpenFor(value: unknown, pane: string): boolean {
  return typeof value === 'object' && value !== null && (value as { pane?: unknown }).pane === pane
}

files.hooks/lang.ts:
// MODZ kit — the interface language: English, or Turkish when the person sets MODZ_LANG=tr (the "env" of
// ~/.claude/settings.json). One value per mod: its register file reads the variable at session.start with
// `setLang(await $.env.get('MODZ_LANG'))` (the engine only admits an env read whose name is a literal), and every
// drawing reads it back through `pick` and `upper`.
export type Lang = 'en' | 'tr'

let current: Lang = 'en'

export const langOf = (value: unknown): Lang => (typeof value === 'string' && /^tr/i.test(value.trim()) ? 'tr' : 'en')

export function setLang(value: unknown): Lang {
  current = langOf(value)

  return current
}

export const lang = (): Lang => current

// The current language's entry of a table that fills in both: `pick({ en: 'Open', tr: 'Aç' })`.
export const pick = <T>(table: Readonly<Record<Lang, T>>): T => table[current]

// Capitals for eyebrows and labels: Turkish keeps its dotted İ, English never gets one.
export const upper = (text: string): string => text.toLocaleUpperCase(current)

