import type { ClientModule, ClientPointerEvent, ClientSurface, RenderElement } from 'claude-code'

export type Seg = { t: string; c?: string; b?: boolean; s?: boolean; i?: boolean; sh?: string; dim?: boolean; one?: boolean; spin?: boolean; bg?: string; tab?: string }
// `bg` tints the whole row while Claude is on that file.
export type RowSpec = { id: string; left: Seg[]; right: Seg[]; bg?: string }
export type RowsProps = {
  rows: RowSpec[]
  active: string
  activeBg: string
  hoverBg: string
  tones: Record<string, { bright: string[]; dim: string[] }>
  spinner?: string[]
  pointer?: boolean
  bar?: { pos: number; size: number; thumb: string; track: string }
}
type Local = { hover: number; phase: number; drag: boolean; ref: { stop?: () => void; unpoint?: () => void } }

const TICK_MS = 90
const FRAMES = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']

// The band's distance from a character to its palette step: brightest at the band's center.
const STEPS = [0.8, 1.8, 2.8]
const BAND_SPEED = 1.6
const BAND_PAD = 4

function shimmer({ i, phase, len }: { i: number; phase: number; len: number }, palette: string[]): string {
  const band = ((phase * BAND_SPEED) % (len + 2 * BAND_PAD)) - BAND_PAD
  const d = Math.abs(i - band)
  const k = STEPS.findIndex(step => d < step)
  return palette[k < 0 ? 0 : STEPS.length - k] ?? palette[0] ?? '#f97316'
}

type Surface = ClientSurface<Local>
type Pointer = ClientPointerEvent

function stateOf(surface: Surface): Local {
  if (surface.state !== undefined) return surface.state
  const state: Local = { hover: -1, phase: 0, drag: false, ref: {} }
  surface.setState(state)
  return state
}

function tick(props: RowsProps, state: Local, surface: Surface): void {
  const lit = props.rows.some(r => r.left.some(s => s.sh || s.spin) || r.right.some(s => s.sh || s.spin))
  if (lit && !state.ref.stop) {
    state.ref.stop = surface.every(TICK_MS, () => {
      const cur = surface.state
      if (cur) surface.setState({ ...cur, phase: cur.phase + 1 })
    })
  } else if (!lit && state.ref.stop) {
    state.ref.stop()
    state.ref.stop = undefined
  }
}

// The scrollbar's column: a press there, and every move until the button lifts, scrolls.
function dragBar(props: RowsProps, cur: Local, { surface, e }: { surface: Surface; e: Pointer }): boolean {
  const onBar = Boolean(props.bar) && e.x >= surface.columns - 1
  if (!props.bar || !(cur.drag || (onBar && e.type === 'down' && (e.button ?? 'left') === 'left'))) return false
  if (e.type === 'up' || e.type === 'leave') {
    surface.setState({ ...cur, drag: false })
    return true
  }
  if (e.type !== 'down' && e.type !== 'move') return false
  if (!cur.drag) surface.setState({ ...cur, drag: true, hover: -1 })
  surface.post({ scrollTo: Math.max(0, Math.min(1, e.y / Math.max(1, props.rows.length - 1))) })
  return true
}

function pressRow(row: RowSpec, surface: Surface, e: Pointer): void {
  let x = 0
  for (const seg of row.left) {
    const w = [...seg.t].length
    if (seg.tab && e.x >= x && e.x < x + w) {
      surface.post({ tab: seg.tab })
      return
    }
    x += w
  }
  if (row.id) surface.post({ press: row.id, ctrl: Boolean(e.ctrl), shift: Boolean(e.shift) })
}

function pointer(props: RowsProps, state: Local, surface: Surface): (e: Pointer) => void {
  return e => {
    const cur = surface.state ?? state
    if (dragBar(props, cur, { surface, e })) return
    if (e.type === 'leave' || e.y < 0 || e.y >= props.rows.length) {
      if (cur.hover !== -1) surface.setState({ ...cur, hover: -1 })
      return
    }
    if (e.type === 'move' && !e.button && cur.hover !== e.y) surface.setState({ ...cur, hover: e.y })
    const row = props.rows[e.y]
    if (e.type === 'down' && e.button === 'right' && row?.id) {
      surface.post({ copy: row.id, shift: Boolean(e.shift) })
      return
    }
    if (e.type !== 'down' || (e.button ?? 'left') !== 'left' || !row) return
    pressRow(row, surface, e)
  }
}

function paletteOf(props: RowsProps, s: Seg): string[] | undefined {
  if (!s.sh) return undefined
  return s.dim ? props.tones[s.sh]?.dim : props.tones[s.sh]?.bright
}

function drawer(props: RowsProps, state: Local, surface: Surface): (s: Seg) => RenderElement {
  const { Text } = surface.elements
  const frames = props.spinner?.length ? props.spinner : FRAMES
  return s => {
    if (s.spin) {
      return (
        <Text color={s.c} bold={s.b}>
          {s.t + (frames[state.phase % frames.length] ?? '')}
        </Text>
      )
    }
    const palette = paletteOf(props, s)
    if (!palette) {
      return (
        <Text color={s.c} backgroundColor={s.bg} bold={s.b} strikethrough={s.s} italic={s.i}>
          {s.t}
        </Text>
      )
    }
    if (s.one) return <Text color={shimmer({ i: -1, phase: state.phase, len: s.t.length }, palette)}>{s.t}</Text>
    const chars = [...s.t]
    return (
      <Text bold={s.b}>
        {chars.map((ch, i) => (
          <Text color={shimmer({ i, phase: state.phase, len: chars.length }, palette)}>{ch}</Text>
        ))}
      </Text>
    )
  }
}

function rowBg(props: RowsProps, r: RowSpec, { i, hover }: { i: number; hover: number }): string | undefined {
  if (r.bg !== undefined) return r.bg
  if (r.id && r.id === props.active) return props.activeBg
  return r.id && i === hover ? props.hoverBg : undefined
}

const Rows: ClientModule<RowsProps, Local> = (props, surface) => {
  const { Box, Text } = surface.elements
  const state = stateOf(surface)
  tick(props, state, surface)
  if (props.pointer === false) {
    state.ref.unpoint?.()
    state.ref.unpoint = undefined
  } else state.ref.unpoint = surface.onPointer(pointer(props, state, surface))
  surface.onKey(e => surface.post({ key: e.key, ctrl: Boolean(e.ctrl), shift: Boolean(e.shift) }))
  const draw = drawer(props, state, surface)
  const isThumb = (i: number) => Boolean(props.bar) && i >= (props.bar?.pos ?? 0) && i < (props.bar?.pos ?? 0) + (props.bar?.size ?? 0)
  return (
    <Box flexDirection="column">
      {props.rows.map((r, i) => (
        <Box flexDirection="row" height={1} overflow="hidden" backgroundColor={rowBg(props, r, { i, hover: state.hover })}>
          <Box flexShrink={1} overflow="hidden">
            {r.left.map(draw)}
          </Box>
          <Box flexGrow={1} />
          {r.right.map(draw)}
          {props.bar && <Text color={isThumb(i) ? props.bar.thumb : props.bar.track}>{isThumb(i) ? '┃' : '│'}</Text>}
        </Box>
      ))}
    </Box>
  )
}

export default Rows

files.hooks/rowspec.ts:
// One tree row as the rows Client draws it: upstream's terminal row, and the desktop row
// with a file-type badge, a role tint while Claude touches the file and a status pill.

import type { FileNode, FileTree, Theme } from '../types'
import { badgeOf } from './badges'
import { TONES } from './git'
import { CHEVRON_CLOSED, CHEVRON_OPEN, fileIcon, GIT_COLOR } from './icons'
import type { RowSpec, Seg } from './rows'
import { folderColor, type Palette, type Role, roleOfTone } from './theme'
import { dirname, formatSize, type Row, stamp, underAny } from './tree'
import { words } from './words'

export type RowCtx = {
  t: FileTree
  bright: ReadonlySet<string>
  dimmed: ReadonlySet<string>
  ignored: ReadonlySet<string>
  untracked: ReadonlySet<string>
  width: number
  now: number
  unicode: boolean
  theme: Theme
  pal: Palette
  // The pill a live row shows in place of its meta: "reading", "editing", ...
  pillOf: (id: string, role: Role) => string
  // What the file's reads put into context this turn ("≈1.2k tok"), or "".
  costOf: (id: string) => string
}

const ADD_COLOR = '#98c379'
const DEL_COLOR = '#e06c75'
const ICON_CELLS = 6

export function clean(segs: Seg[]): Seg[] {
  for (const seg of segs) for (const k of Object.keys(seg) as (keyof Seg)[]) if (seg[k] === undefined) delete seg[k]
  return segs
}

export function countSegs(c: [number, number, number] | undefined, theme: Theme): Seg[] {
  if (!c) return []
  const out: Seg[] = []
  if (c[0] > 0) out.push({ t: ` ?:${c[0]}`, c: GIT_COLOR['?'] ?? ADD_COLOR })
  if (c[1] > 0) out.push({ t: ` M:${c[1]}`, c: GIT_COLOR.M ?? '#e5c07b' })
  if (c[2] > 0) out.push({ t: ` D:${c[2]}`, c: theme.urgent })
  return out
}

function statusOf(ctx: RowCtx, id: string): string | undefined {
  return ctx.t.git[id] ?? (underAny(dirname(id), ctx.untracked, ctx.t.root) ? '?' : undefined)
}

function metaOf(ctx: RowCtx, r: Row): string {
  const { t } = ctx
  const n = r.node
  if (t.showSize) {
    if (n.kind === 'dir') return n.id in t.dirSizes ? formatSize(t.dirSizes[n.id] ?? -1) : '…'
    return n.kind === 'file' || (n.kind === 'link' && n.size > 0) ? formatSize(n.size) : ''
  }
  return t.diff[n.id] || n.kind !== 'file' ? '' : stamp(n.mtime, ctx.now)
}

const fit = (name: string, cols: number): string => (name.length > cols ? name.slice(0, Math.max(1, cols - 1)) + '…' : name)

function gitColorOf(status: string | undefined, theme: Theme): string | undefined {
  if (status === 'D' || status === 'U') return theme.urgent
  return status ? (GIT_COLOR[status] ?? theme.muted) : undefined
}

function terminalColors(theme: Theme, n: FileNode, git: { color: string | undefined; isIgnored: boolean }) {
  if (git.isIgnored) return { icon: theme.muted, name: theme.muted }
  if (git.color !== undefined) return { icon: git.color, name: git.color }
  if (n.hidden) return { icon: theme.muted, name: theme.muted }
  return { icon: n.kind === 'dir' ? theme.accent : theme.muted, name: theme.fg || undefined }
}

function badgeText(ctx: RowCtx, s: { status: string | undefined; isIgnored: boolean; hasCounts: boolean }): string {
  if (s.hasCounts) return ''
  if (s.status) return ` ${s.status}`
  if (!s.isIgnored) return '  '
  return ctx.unicode ? ' ⊘' : ' \u{f05e}'
}

function caretOf(r: Row, unicode: boolean): string {
  if (r.node.kind !== 'dir') return '  '
  if (unicode) return (r.open ? '▾' : '▸') + ' '
  return (r.open ? CHEVRON_OPEN : CHEVRON_CLOSED) + ' '
}

function glyphOf(ctx: RowCtx, r: Row): string {
  const n = r.node
  if (!ctx.unicode) return fileIcon(n, r.open, n.kind === 'dir' && n.id === ctx.t.top)
  return n.kind === 'dir' ? '■' : '·'
}

export function terminalRow(ctx: RowCtx, r: Row): RowSpec {
  const { t, theme, unicode } = ctx
  const n = r.node
  const status = statusOf(ctx, n.id)
  const isIgnored = !status && underAny(n.id, ctx.ignored, t.root)
  const gitColor = gitColorOf(status, theme)
  const isBright = ctx.bright.has(n.id)
  const isDim = !isBright && ctx.dimmed.has(n.id)
  const tone = t.flashTones[n.id] ?? 'orange'
  const colors = terminalColors(theme, n, { color: gitColor, isIgnored })
  const loc = t.diff[n.id]
  const meta = metaOf(ctx, r)
  const cost = ctx.costOf(n.id)
  const locText = loc ? `${loc[0] ? ` +${loc[0]}` : ''}${loc[1] ? ` -${loc[1]}` : ''}` : ''
  const dirCounts = n.kind === 'dir' ? countSegs(t.counts[n.id], theme) : []
  const badge = badgeText(ctx, { status, isIgnored, hasCounts: dirCounts.length > 0 })
  const countsText = dirCounts.map(c => c.t).join('')
  const cols = Math.max(4, ctx.width - r.depth * 2 - 6 - (meta ? meta.length + 1 : 0) - (cost ? cost.length + 1 : 0) - locText.length - badge.length - countsText.length)
  const caret = caretOf(r, unicode)
  const glyph = glyphOf(ctx, r)
  const lit = isBright || isDim
  const left: Seg[] = [
    { t: '  '.repeat(r.depth) },
    { t: caret, c: theme.muted },
    lit ? { t: glyph + ' ', sh: tone, dim: isDim, one: true } : { t: glyph + ' ', c: colors.icon },
    lit ? { t: fit(n.name, cols), sh: tone, dim: isDim, b: isBright } : { t: fit(n.name, cols), c: colors.name, b: n.id === t.selected, s: status === 'D' && n.kind !== 'dir' },
  ]
  const right: Seg[] = []
  if (cost) right.push({ t: ` ${cost}`, c: TONES.blue?.solid ?? theme.accent })
  if (meta) right.push({ t: ` ${meta}`, c: theme.muted })
  if (loc && loc[0] > 0) right.push({ t: ` +${loc[0]}`, c: ADD_COLOR })
  if (loc && loc[1] > 0) right.push({ t: ` -${loc[1]}`, c: DEL_COLOR })
  right.push(...dirCounts)
  if (badge) right.push({ t: badge, c: status ? gitColor : theme.muted, b: true })
  return { id: n.id, left: clean(left), right: clean(right) }
}

function folderGlyphColor(pal: Palette, n: FileNode, changes: number): string {
  if (n.hidden) return pal.lo
  return changes ? pal.roles.warn.fg : folderColor(pal)
}

function desktopIcon(ctx: RowCtx, r: Row, role: Role | null): Seg[] {
  const { pal } = ctx
  const n = r.node
  if (n.kind === 'dir') {
    const changes = (ctx.t.counts[n.id] ?? [0, 0, 0]).reduce((a, b) => a + b, 0)
    const color = folderGlyphColor(pal, n, changes)
    const glyph = { t: '■', c: role ? pal.roles[role].fg : color }
    return [{ t: r.open ? '▾ ' : '▸ ', c: pal.lo }, glyph, { t: ' '.repeat(ICON_CELLS - 3) }]
  }
  const kind = badgeOf(n.name)
  const colors = role ? { fg: pal.roles[role].fg, bg: pal.roles[role].line } : { fg: pal.roles[kind.role].fg, bg: pal.roles[kind.role].tint }
  const label = ` ${kind.label} `
  return [{ t: label, c: colors.fg, bg: colors.bg, b: true }, { t: ' '.repeat(Math.max(1, ICON_CELLS - label.length)) }]
}

function desktopRight(ctx: RowCtx, r: Row, role: Role | null): Seg[] {
  const { t, pal } = ctx
  const n = r.node
  if (role) {
    const text = ctx.pillOf(n.id, role)
    if (text) return [{ t: ' ' }, { t: ` ${text} `, c: pal.roles[role].fg, bg: pal.roles[role].line, b: true }]
  }
  const changes = n.kind === 'dir' ? (t.counts[n.id] ?? [0, 0, 0]).reduce((a, b) => a + b, 0) : 0
  if (changes && !t.showSize) return [{ t: ` ${words().changes(changes)}`, c: pal.roles.warn.fg, b: true }]
  const loc = t.diff[n.id]
  const out: Seg[] = []
  if (loc && !t.showSize) {
    if (loc[0] > 0) out.push({ t: ` +${loc[0]}`, c: pal.roles.ok.fg })
    if (loc[1] > 0) out.push({ t: ` −${loc[1]}`, c: pal.roles.danger.fg })
  }
  const cost = ctx.costOf(n.id)
  if (cost) out.push({ t: ` ${cost}`, c: pal.roles.read.fg })
  const meta = metaOf(ctx, r)
  if (meta) out.push({ t: ` ${meta}`, c: pal.lo })
  return out
}

function nameColor(ctx: RowCtx, id: string, isHidden: boolean): string {
  const { pal } = ctx
  const status = statusOf(ctx, id)
  if (status === 'D' || status === 'U') return pal.roles.danger.fg
  if (status) return pal.roles.warn.fg
  return isHidden || underAny(id, ctx.ignored, ctx.t.root) ? pal.lo : pal.hi
}

export function desktopRow(ctx: RowCtx, r: Row): RowSpec {
  const { t } = ctx
  const n = r.node
  const isBright = ctx.bright.has(n.id)
  const isDim = !isBright && ctx.dimmed.has(n.id)
  const tone = t.flashTones[n.id] ?? 'orange'
  const role = isBright ? roleOfTone(tone) : null
  const right = desktopRight(ctx, r, role)
  const rightLen = right.reduce((s, x) => s + x.t.length, 0)
  const cols = Math.max(4, ctx.width - r.depth * 2 - ICON_CELLS - rightLen - 2)
  const name = fit(n.name, cols)
  const status = statusOf(ctx, n.id)
  const label: Seg = isBright || isDim
    ? { t: name, sh: tone, dim: isDim, b: true }
    : { t: name, c: nameColor(ctx, n.id, n.hidden), b: n.id === t.selected || Boolean(status && n.kind !== 'dir'), s: status === 'D' && n.kind !== 'dir' }
  const left: Seg[] = [{ t: '  '.repeat(r.depth) }, ...desktopIcon(ctx, r, role), label]
  return { id: n.id, left: clean(left), right: clean(right), ...(role ? { bg: ctx.pal.roles[role].tint } : {}) }
}

